CREATE OR ALTER PROCEDURE dbo.SP_OBTENER_EVALUACION  (      @EvaluacionId INT  )  AS  BEGIN      SET NOCOUNT ON;        DECLARE            @EvaluacionPadreId INT          , @VersionFaseId     INT          , @VersionId         INT;        /* =============================================================         0. CONTEXTO DE LA EVALUACION         ============================================================= */        SELECT            @EvaluacionPadreId = E.EvaluacionPadreId          , @VersionFaseId     = E.VersionFaseId          , @VersionId         = L.VersionId      FROM dbo.EVALUACION E      INNER JOIN dbo.LOTE L          ON L.LoteId = E.LoteId      WHERE E.EvaluacionId = @EvaluacionId        AND E.Estado = 'ACTIVO';          /* =============================================================         RESULTSET 1         CABECERA         ============================================================= */        SELECT            E.EvaluacionId          , L.LoteId          , L.CodigoLote            /* ---------------------------------------------------------             PRODUCTO / PRESENTACION             --------------------------------------------------------- */            , COALESCE            (                L.ProductoCodigo,                D.ProductoCodigo            ) AS ProductoCodigo            , L.CodigoGenesis            , CASE                WHEN L.CodigoGenesis IS NOT NULL                    THEN GI.NombreGenesis                ELSE P.ProductoDescripcion            END AS ProductoDescripcion            , GI.Kardex              /* ---------------------------------------------------------             DOCUMENTO / ESPECIFICACION TECNICA             --------------------------------------------------------- */            , D.DocumentoId          , D.DocumentoCodigo          , D.DocumentoDescripcionDocumento              /* ---------------------------------------------------------             VERSION UTILIZADA             --------------------------------------------------------- */            , V.VersionId          , V.VersionNumero              /* ---------------------------------------------------------             ETAPA DE EVALUACION             --------------------------------------------------------- */            , E.VersionFaseId            , VF.Orden              AS VersionFaseOrden            , VF.CodigoReferencia            , VF.Descripcion              AS VersionFaseDescripcion            , VF.FaseId            , F.Codigo              AS FaseCodigo            , F.Descripcion              AS FaseDescripcion            , VF.EsFinal            , VF.EsObligatoria              AS VersionFaseEsObligatoria              /* ---------------------------------------------------------             TIPO DE EVALUACION             --------------------------------------------------------- */            , E.TipoEvaluacionId            , TE.Codigo              AS TipoEvaluacion              /* ---------------------------------------------------------             ESTADO DE EVALUACION             --------------------------------------------------------- */            , E.EstadoEvaluacionId            , EE.Codigo              AS EstadoEvaluacion              /* ---------------------------------------------------------             EVALUACION             --------------------------------------------------------- */            , E.Intento          , E.EvaluacionPadreId          , E.UsuarioEvaluador          , E.FechaInicio          , E.FechaFin          , E.MotivoReevaluacion          , E.Observacion          , E.ResultadoGeneral              /* ---------------------------------------------------------             INDICADOR DE REEVALUACION             --------------------------------------------------------- */            , CASE                WHEN E.EvaluacionPadreId IS NOT NULL                    THEN CAST(1 AS BIT)                ELSE CAST(0 AS BIT)            END AS EsReevaluacion          FROM dbo.EVALUACION E        INNER JOIN dbo.LOTE L          ON E.LoteId = L.LoteId        INNER JOIN dbo.VERSION V          ON L.VersionId = V.VersionId        INNER JOIN dbo.DOCUMENTO D          ON V.DocumentoId = D.DocumentoId        LEFT JOIN dbo.PRODUCTO P          ON L.ProductoCodigo = P.ProductoCodigo        LEFT JOIN dbo.GENESIS_ITEM GI          ON L.CodigoGenesis = GI.CodigoGenesis        INNER JOIN dbo.TIPO_EVALUACION TE          ON E.TipoEvaluacionId = TE.TipoEvaluacionId        INNER JOIN dbo.ESTADO_EVALUACION EE          ON E.EstadoEvaluacionId = EE.EstadoEvaluacionId        LEFT JOIN dbo.VERSIONFASE VF          ON E.VersionFaseId = VF.VersionFaseId        LEFT JOIN dbo.FASE F          ON VF.FaseId = F.FaseId        WHERE E.EvaluacionId = @EvaluacionId;          /* =============================================================         RESULTSET 2         CARACTERISTICAS / RESULTADOS           EVALUACION NORMAL:             Todas las características de la etapa.           REEVALUACION:             Únicamente características que en el padre inmediato             quedaron con Cumple = 0.         ============================================================= */        SELECT            VC.VersCaractId              /* ---------------------------------------------------------             ETAPA             --------------------------------------------------------- */            , VC.VersionFaseId            , VF.Orden              AS VersionFaseOrden            , VF.CodigoReferencia            , VF.EsFinal              /* ---------------------------------------------------------             ORDEN GENERAL             --------------------------------------------------------- */            , ROW_NUMBER() OVER            (                ORDER BY                    TC.TipoCaractId,                    VC.Orden            ) AS OrdenGeneral              /* ---------------------------------------------------------             TIPO CARACTERISTICA             --------------------------------------------------------- */            , TC.TipoCaractId            , TC.TipoCaractDescripcion              AS TipoCaracteristica              /* ---------------------------------------------------------             ITEM DENTRO DEL GRUPO             --------------------------------------------------------- */            , ROW_NUMBER() OVER            (                PARTITION BY TC.TipoCaractId                ORDER BY VC.Orden            ) AS Item              /* ---------------------------------------------------------             INICIO DE GRUPO             --------------------------------------------------------- */            , CASE                WHEN ROW_NUMBER() OVER                (                    PARTITION BY TC.TipoCaractId                    ORDER BY VC.Orden                ) = 1                    THEN CAST(1 AS BIT)                ELSE CAST(0 AS BIT)            END AS EsInicioGrupo              /* ---------------------------------------------------------             ORDEN CONFIGURADO             --------------------------------------------------------- */            , VC.Orden              /* ---------------------------------------------------------             FASE             --------------------------------------------------------- */            , ISNULL(F.Codigo, '')              AS Fase              /* ---------------------------------------------------------             CARACTERISTICA             --------------------------------------------------------- */            , C.CaracteristicaId            , C.CaracteristicaDescripcion              AS Caracteristica            , COALESCE            (                NULLIF(VC.UnidadDeMedida, ''),                C.CaracteristicaUnidadDeMedida            ) AS Unidad            , M.MetEnsayoDescripcion              AS MetodoEnsayo              /* ---------------------------------------------------------             CRITERIO             --------------------------------------------------------- */            , CR.TipoCriterioId            , CR.TipCritDescripcion              AS TipoCriterio              /* ---------------------------------------------------------             OBLIGATORIEDAD             --------------------------------------------------------- */            , VC.EsObligatorio              /* ---------------------------------------------------------             VALORES DE ESPECIFICACION             --------------------------------------------------------- */            , VC.ValorCuantitativoInicial          , VC.ValorCuantitativoFinal          , VC.ValorCuantitativoIgual          , VC.ValorCualitativo              /* ---------------------------------------------------------             ESPECIFICACION FORMATEADA             --------------------------------------------------------- */            , CASE CR.TipCritDescripcion                  WHEN 'MINIMO'                    THEN CONCAT                    (                        N'≥ ',                        FORMAT                        (                            VC.ValorCuantitativoInicial,                            '0.####'                        )                    )                  WHEN 'MAXIMO'                    THEN CONCAT                    (                        N'≤ ',                        FORMAT                        (                            VC.ValorCuantitativoFinal,                            '0.####'                        )                    )                  WHEN 'MAYOR_QUE'                    THEN CONCAT                    (                        N'> ',                        FORMAT                        (                            VC.ValorCuantitativoInicial,                            '0.####'                        )                    )                  WHEN 'MENOR_QUE'                    THEN CONCAT                    (                        N'< ',                        FORMAT                        (                            VC.ValorCuantitativoFinal,                            '0.####'                        )                    )                  WHEN 'RANGO'                    THEN CONCAT                    (                        FORMAT                        (                            VC.ValorCuantitativoInicial,                            '0.####'                        ),                        ' - ',                        FORMAT                        (                            VC.ValorCuantitativoFinal,                            '0.####'                        )                    )                  WHEN 'IGUAL'                    THEN CONCAT                    (                        '= ',                        FORMAT                        (                            VC.ValorCuantitativoIgual,                            '0.####'                        )                    )                  WHEN 'AUSENCIA'                    THEN VC.ValorCualitativo                  WHEN 'CUALITATIVO'                    THEN VC.ValorCualitativo                  ELSE ''              END AS Especificacion              /* ---------------------------------------------------------             TIPO DE RESULTADO             --------------------------------------------------------- */            , CASE                  WHEN CR.TipCritDescripcion IN                (                    'MINIMO',                    'MAXIMO',                    'RANGO',                    'MAYOR_QUE',                    'MENOR_QUE',                    'IGUAL'                )                    THEN 'NUMERICO'                  ELSE 'TEXTO'              END AS TipoResultado              /* ---------------------------------------------------------             RESULTADO DEL INTENTO ACTUAL             --------------------------------------------------------- */            , ER.EvaluacionResultadoId          , ER.ResultadoTexto          , ER.ResultadoNumerico              /* ---------------------------------------------------------             RESULTADO FORMATEADO             --------------------------------------------------------- */            , COALESCE            (                ER.ResultadoTexto,                  FORMAT                (                    ER.ResultadoNumerico,                    '0.####'                ),                  ''            ) AS Resultado              /* ---------------------------------------------------------             OBSERVACION             --------------------------------------------------------- */            , ER.Observacion              /* ---------------------------------------------------------             CUMPLIMIENTO             --------------------------------------------------------- */            , ER.Cumple            , CASE                WHEN ER.Cumple IS NULL                    THEN ''                  WHEN ER.Cumple = 1                    THEN 'CUMPLE'                  ELSE 'NO CUMPLE'              END AS CumpleDescripcion              /* ---------------------------------------------------------             TIENE RESULTADO             --------------------------------------------------------- */            , CASE                WHEN ER.EvaluacionResultadoId IS NULL                    THEN CAST(0 AS BIT)                ELSE CAST(1 AS BIT)            END AS TieneResultado              /* ---------------------------------------------------------             TIENE OBSERVACION             --------------------------------------------------------- */            , CASE                WHEN ISNULL(ER.Observacion, '') = ''                    THEN CAST(0 AS BIT)                ELSE CAST(1 AS BIT)            END AS TieneObservacion              /* ---------------------------------------------------------             EDICION             --------------------------------------------------------- */            , CASE                WHEN EE.Codigo = 'EN_PROCESO'                    THEN CAST(1 AS BIT)                ELSE CAST(0 AS BIT)            END AS PermiteEditar              /* ---------------------------------------------------------             TRAZABILIDAD DE REEVALUACION               Estos campos permiten al frontend saber que el parámetro             proviene de un incumplimiento anterior.             --------------------------------------------------------- */            , @EvaluacionPadreId              AS EvaluacionPadreId            , ERP.EvaluacionResultadoId              AS EvaluacionResultadoPadreId            , ERP.ResultadoTexto              AS ResultadoTextoAnterior            , ERP.ResultadoNumerico              AS ResultadoNumericoAnterior            , ERP.Cumple              AS CumpleAnterior            , ERP.Observacion              AS ObservacionAnterior          FROM dbo.EVALUACION E        INNER JOIN dbo.LOTE L          ON E.LoteId = L.LoteId          INNER JOIN dbo.VERSIONCARACTERISTICA VC          ON L.VersionId = VC.VersionId           AND         (             E.VersionFaseId IS NULL             OR VC.VersionFaseId = E.VersionFaseId         )          INNER JOIN dbo.CARACTERISTICA C          ON VC.CaracteristicaId = C.CaracteristicaId          INNER JOIN dbo.TIPO_CARACTERISTICA TC          ON C.TipoCaractId = TC.TipoCaractId          INNER JOIN dbo.TIPO_CRITERIO CR          ON VC.TipoCriterioId = CR.TipoCriterioId          INNER JOIN dbo.METODO_DE_ENSAYO M          ON C.MetEnsayoId = M.MetEnsayoId          INNER JOIN dbo.ESTADO_EVALUACION EE          ON E.EstadoEvaluacionId = EE.EstadoEvaluacionId          LEFT JOIN dbo.VERSIONFASE VF          ON VC.VersionFaseId = VF.VersionFaseId          LEFT JOIN dbo.FASE F          ON F.FaseId =             COALESCE             (                 VF.FaseId,                 VC.FaseId             )          /* -------------------------------------------------------------         RESULTADO DEL INTENTO ACTUAL         ------------------------------------------------------------- */        LEFT JOIN dbo.EVALUACION_RESULTADO ER          ON ER.EvaluacionId = E.EvaluacionId         AND ER.VersCaractId = VC.VersCaractId         AND ER.Estado = 'ACTIVO'          /* -------------------------------------------------------------         RESULTADO DEL PADRE           Solo tendrá valor cuando exista EvaluacionPadreId.         ------------------------------------------------------------- */        LEFT JOIN dbo.EVALUACION_RESULTADO ERP          ON ERP.EvaluacionId = E.EvaluacionPadreId         AND ERP.VersCaractId = VC.VersCaractId         AND ERP.Estado = 'ACTIVO'          WHERE E.EvaluacionId = @EvaluacionId          AND VC.Estado = 1            /* ===========================================================           REGLA DE REEVALUACION SELECTIVA             Normal:               EvaluacionPadreId NULL               -> todas las características de la etapa.             Reevaluación:               EvaluacionPadreId con valor               -> únicamente las que NO CUMPLIERON en el padre.           =========================================================== */          AND        (            E.EvaluacionPadreId IS NULL              OR            (                ERP.EvaluacionResultadoId IS NOT NULL                AND ERP.Cumple = 0            )        )          ORDER BY            TC.TipoCaractId          , VC.Orden;          /* =============================================================         RESULTSET 3         AVANCE           IMPORTANTE:         En reevaluación el denominador también debe considerar         únicamente los parámetros que fallaron en el padre.         ============================================================= */        SELECT              COUNT(*)                AS TotalCaracteristicas              /* ---------------------------------------------------------             TOTAL OBLIGATORIAS             --------------------------------------------------------- */            , SUM            (                CASE                    WHEN VC.EsObligatorio = 1                        THEN 1                    ELSE 0                END            ) AS TotalObligatorias              /* ---------------------------------------------------------             RESULTADOS REGISTRADOS             --------------------------------------------------------- */            , SUM            (                CASE                    WHEN ER.EvaluacionResultadoId IS NOT NULL                        THEN 1                    ELSE 0                END            ) AS ResultadosRegistrados              /* ---------------------------------------------------------             OBLIGATORIAS COMPLETAS             --------------------------------------------------------- */            , SUM            (                CASE                    WHEN VC.EsObligatorio = 1                     AND ER.EvaluacionResultadoId IS NOT NULL                        THEN 1                    ELSE 0                END            ) AS ObligatoriasCompletas              /* ---------------------------------------------------------             PARAMETROS PENDIENTES             --------------------------------------------------------- */            , SUM            (                CASE                    WHEN ER.EvaluacionResultadoId IS NULL                        THEN 1                    ELSE 0                END            ) AS ParametrosPendientes              /* ---------------------------------------------------------             PORCENTAJE DE AVANCE             --------------------------------------------------------- */            , CAST            (                SUM                (                    CASE                        WHEN ER.EvaluacionResultadoId IS NOT NULL                            THEN 1                        ELSE 0                    END                )                * 100.0                /                NULLIF(COUNT(*), 0)                  AS DECIMAL(5,2)            ) AS PorcentajeAvance          FROM dbo.EVALUACION E        INNER JOIN dbo.LOTE L          ON E.LoteId = L.LoteId          INNER JOIN dbo.VERSIONCARACTERISTICA VC          ON L.VersionId = VC.VersionId           AND         (             E.VersionFaseId IS NULL             OR VC.VersionFaseId = E.VersionFaseId         )          LEFT JOIN dbo.EVALUACION_RESULTADO ER          ON ER.EvaluacionId = E.EvaluacionId         AND ER.VersCaractId = VC.VersCaractId         AND ER.Estado = 'ACTIVO'          LEFT JOIN dbo.EVALUACION_RESULTADO ERP          ON ERP.EvaluacionId = E.EvaluacionPadreId         AND ERP.VersCaractId = VC.VersCaractId         AND ERP.Estado = 'ACTIVO'          WHERE E.EvaluacionId = @EvaluacionId          AND VC.Estado = 1          AND        (            E.EvaluacionPadreId IS NULL              OR            (                ERP.EvaluacionResultadoId IS NOT NULL                AND ERP.Cumple = 0            )        );    END;
GO
